INSERT INTO dh_market_approval_work_order (
    source_system, source_record_id, mart_source_id, mart_name, applicant_key, applicant_name,
    applicant_dept_name, apply_type, start_time, end_time, apply_time, apply_reason, source_status,
    source_approval_reason, source_approval_time, detail_snapshot, local_status,
    local_approval_reason, local_check_user_id, local_check_time, revision, creator, updater
)
SELECT 'QDATA', t.source_record_id, t.mart_source_id, t.mart_name, t.applicant_key, t.applicant_name,
       t.applicant_dept_name, t.apply_type::smallint, t.start_time::timestamp, t.end_time::timestamp,
       t.apply_time::timestamp, t.apply_reason, t.source_status, t.source_approval_reason, NULL,
       COALESCE(s.detail_snapshot, '{}'::jsonb) || jsonb_build_object('sourceMetadata',
           jsonb_build_object('sourceCreateTime', t.apply_time, 'sourceUpdateTime', t.source_update_time,
                              'capturedAt', '2026-10-22T16:56:44.658Z')),
       NULL, NULL, NULL, NULL, 1, 'migration:qdata-approval', 'migration:qdata-approval'
FROM source_tickets t
LEFT JOIN source_snapshots s ON s.mart_source_id = t.mart_source_id
ON CONFLICT (source_system, source_record_id) DO NOTHING;

COMMIT;
